<?php
require __DIR__.'/app/core.php';require __DIR__.'/app/install.php';
if(!in_array($_SERVER['REMOTE_ADDR']??'',['127.0.0.1','::1'],true)){http_response_code(403);exit('Run initial setup from localhost on the server computer.');}
$error='';$done=false;
try{$done=(int)val('SELECT COUNT(*) FROM users')>0;}catch(Throwable $e){}
if($done)go('login.php');
if($_SERVER['REQUEST_METHOD']==='POST')try{
    guard();$name=textval($_POST['full_name']??'',100);$username=strtolower(textval($_POST['username']??'',50));$password=(string)($_POST['password']??'');
    if(!preg_match('/^[a-z0-9_.-]{3,50}$/D',$username))throw new RuntimeException('Username must be 3–50 letters, numbers, dots, underscores or hyphens.');
    if(strlen($password)<10||strlen($password)>72)throw new RuntimeException('Choose a password with 10 to 72 characters.');
    if($password!==($_POST['confirm_password']??''))throw new RuntimeException('Passwords do not match.');
    installSchema();tx(function()use($name,$username,$password){if(val('SELECT COUNT(*) FROM users'))throw new RuntimeException('Setup has already finished.');$id=insert('users',['role_id'=>1,'full_name'=>$name,'username'=>$username,'password_hash'=>password_hash($password,PASSWORD_DEFAULT),'is_active'=>1]);if(isset($_POST['starter']))seedStarter($id);});
    flash('Your workspace is ready. Sign in with your owner account.');go('login.php');
}catch(Throwable $e){$error=$e instanceof PDOException?'Cannot connect or install. Start MySQL in XAMPP and check config/database.php. If your database is partially installed, use a new empty database name.':safeError($e);error_log((string)$e);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Set up CarinderEase</title><link rel="stylesheet" href="assets/app.css"></head><body class="auth-body"><main class="auth-card setup"><a class="brand" href="login.php"><span class="brand-mark">C<span>✦</span></span>Carinder<span>Ease</span></a><div class="eyebrow">WELCOME TO YOUR NEW COUNTER</div><h1>Good food.<br>Better flow.</h1><p class="muted">Create your one Owner / Admin account. Setup runs once on this computer and locks after your account is created.</p><?php if($error):?><div class="notice error"><?=h($error)?></div><?php endif?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Full name<input name="full_name" required maxlength="100" autocomplete="name" value="<?=h($_POST['full_name']??'')?>"></label><label>Owner username<input name="username" required pattern="[A-Za-z0-9_.-]{3,50}" autocomplete="username" value="<?=h($_POST['username']??'')?>"></label><label>Password<input name="password" type="password" required minlength="10" maxlength="72" autocomplete="new-password"></label><label>Confirm password<input name="confirm_password" type="password" required minlength="10" maxlength="72" autocomplete="new-password"></label><label class="check full"><input type="checkbox" name="starter" checked> Include sample dishes, today’s menu, and ingredient stock</label><p class="hint full">Starter records are demonstration data. No sample sales, expenses, or other employee accounts are created.</p><button class="btn primary full">Create my workspace →</button></form><p><a href="import-family.php">Already have CarinderEase records? Import your family business instead.</a></p><p class="hint">PHP 8.1+ · MySQL 8.0+ / MariaDB 10.4+ · XAMPP</p></main></body></html>
